import { readFileSync } from "node:fs";
import { expect, it } from "vitest";
import {
  replayFiveMinute,
  replaySignalSeries,
  replayDailyStudy,
  replayAllocationStudy,
} from "quant-backtest";
import {
  factorStrategyPresets,
  factorStrategySchema,
  studyStrategies,
  type StudyStrategy,
} from "trading-strategies";
import { maCrossStrategy } from "../../helpers/legacy-ma-signals";
import {
  parityFiveMinute,
  parityDaily,
  parityAllocation,
} from "../../helpers/portfolio-parity";

// Generated by running commit 326d5c7 on deterministic inputs, before removing
// its entrypoints. The frozen outputs remain independent of the replacement.
const expected = JSON.parse(
  readFileSync("tests/fixtures/r1b-engine-parity.json", "utf8"),
) as {
  five: unknown;
  factor: unknown;
  signals: unknown;
  daily: Record<string, unknown>;
  allocation: Record<string, unknown>;
};
// P3 moved portfolio settlement to bigint atoms. Cash/equity checkpoints can
// differ from the number ledger by binary64 rounding far below one cent.
function nearMoney(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(nearMoney);
  if (value && typeof value === "object")
    return Object.fromEntries(
      Object.entries(value).map(([key, entry]) => [
        key,
        typeof entry === "number" &&
        ["cash", "cashAfter", "value", "equity"].includes(key)
          ? Number(entry.toFixed(9))
          : nearMoney(entry),
      ]),
    );
  return value;
}
function fiveFields(
  r:
    ReturnType<typeof replayFiveMinute> | ReturnType<typeof replaySignalSeries>,
) {
  return {
    fills: r.fills,
    orders: r.orders,
    equity: r.equity,
    cash: r.cash,
    shares: r.shares,
  };
}
it("runBacktest, runMaBaseline and runStrategyExperiment fills / orders / equity match the frozen pre-R1b engines", () => {
  const { input, bars } = parityFiveMinute();
  expect(nearMoney(fiveFields(replayFiveMinute(input, bars)))).toEqual(
    nearMoney(expected.five),
  );
  expect(
    nearMoney(
      fiveFields(
        replayFiveMinute(
          {
            ...input,
            strategy: factorStrategySchema.parse(factorStrategyPresets[1]),
          },
          bars,
        ),
      ),
    ),
  ).toEqual(nearMoney(expected.factor));
  expect(
    nearMoney(
      fiveFields(
        replaySignalSeries(input, bars, maCrossStrategy(bars), {
          evidence: "fixture",
          minimumBuy: 100,
          buyStep: 100,
          maximumOrder: 100000000,
          limitUp: null,
          limitDown: null,
          tradable: true,
        }),
      ),
    ),
  ).toEqual(nearMoney(expected.signals));
});
// This fixture predates the theory proxies. Its keys are the historical
// preservation contract; new rules have independent causal/geometry tests.
it("retains every strategy recorded by the frozen pre-R1b engine", () => {
  expect(Object.keys(expected.daily)).toHaveLength(56);
  for (const id of Object.keys(expected.daily))
    expect(studyStrategies).toContain(id);
});
it.each(Object.keys(expected.daily) as StudyStrategy[])(
  "runClassicStudy %s preserves every fill and daily equity including segregated dividends",
  (strategy) => {
    const { bars, dividends, options } = parityDaily();
    const r = replayDailyStudy(bars, dividends, { ...options, strategy });
    expect({
      fills: r.fills,
      curve: r.curve,
      dividends: r.dividends,
      fees: r.fees,
      rejected: r.rejected,
    }).toEqual(expected.daily[strategy]);
  },
);
it.each(["equal-pool", "momentum", "risk-weighted", "regime"] as const)(
  "runCsi800Study %s preserves every fill, holding and equity",
  (mode) => {
    const { stocks, benchmark, options } = parityAllocation();
    const r = replayAllocationStudy(stocks, benchmark, { ...options, mode });
    expect({
      fills: r.fills,
      curve: r.curve,
      snapshots: r.snapshots,
      rebalances: r.rebalances,
      rejected: r.rejected,
    }).toEqual(expected.allocation[mode]);
  },
);
